// Report closure over the real producer shapes: child Proposals generated by
// accepting a Claim Candidate / relation discovery packet (packet context
// nested under `payload.metadata`), and schema suggestions counting published
// Project public summaries. Every case runs the production producer, persists
// through its real writer and reads back through the DTO/accept paths.
import {randomUUID} from 'node:crypto';
import {afterEach,beforeEach,describe,expect,it} from 'vitest';
import {useTestDatabase} from './support/testDatabase.js';
import {resetTables} from './support/resetTables.js';
import {seedSpaceOwnerProject,seedSpaceMember} from './support/domainSeeds.js';
import {insertKnowledgeItem} from './support/knowledgeFixtures.js';
import {buildModuleServer} from './support/moduleServer.js';
import {seedSourceConnection} from './support/reviewPacketDatabase.js';
import {waitForBlockedBy} from './support/lockWait.js';
import {claimJobForHandler} from './support/jobClaim.js';
import {knowledgeModule} from '../src/modules/knowledge/index.js';
import {memoryModule} from '../src/modules/memory/index.js';
import {systemActionsModule} from '../src/modules/systemActions/index.js';
import {artifactsModule} from '../src/modules/artifacts/index.js';
import {contextOpsModule} from '../src/modules/contextOps/index.js';
import {projectsModule} from '../src/modules/projects/index.js';
import {proposalsModule,__setProposalIdentityForTests} from '../src/modules/proposals/index.js';
import {__setAuthIdentityForTests} from '../src/modules/auth/identity.js';
import {assertArtifactReadable} from '../src/modules/reader/repository.js';
import {createClaimCandidatePacketFromArtifacts} from '../src/modules/knowledge/claimCandidatePackets.js';
import {insertArtifactRow} from '../src/modules/artifacts/reviewArtifactWriter.js';
import {registerContentRetrievalJob} from '../src/modules/retrieval/contentRequests.js';
import {JobHandlerRegistry} from '../src/modules/jobs/handlerRegistry.js';
import {PgJobQueueRepository} from '../src/modules/jobs/repository.js';
import {RetrievalProjectionService} from '../src/modules/retrieval/projectionService.js';
import {knowledgeRetrievalRegistry} from '../src/modules/knowledge/retrievalAdapter.js';
import {contentDecisionFromDb} from '../src/modules/access/contentAccessQuery.js';
import {proposalReportDependencies} from '../src/modules/retrieval/proposalReportDependencies.js';
import {loadConfig} from '../src/config.js';

const db=useTestDatabase(import.meta.filename,{max:6});
let space:string,owner:string,project:string,item:string,connection:string,sourceItem:string,app:ReturnType<typeof buildModuleServer>;
const config=()=>loadConfig({SERVER_DATABASE_URL:db.connectionUri});
const identity=()=>({spaceId:space,userId:owner});
const call=(operation:string,payload:object,key=randomUUID())=>app.inject({method:'POST',url:'/api/v1/actions/'+operation,payload,headers:{'idempotency-key':key}});
const consent=(admins:boolean,sourceOwner:string)=>({schema_version:1,owner_user_id:sourceOwner,allowed_reader_user_ids:[],allowed_agent_ids:[],allow_space_admins:admins});
let sourceOwner:string;
const setConsent=(allowed:boolean,q:{query:(sql:string,params:unknown[])=>Promise<unknown>}=db.pool)=>q.query('UPDATE source_connections SET consent_json=$2::jsonb WHERE id=$1',[connection,JSON.stringify(consent(allowed,sourceOwner))]);
/** A Knowledge item whose accepted provenance is an item of the Source connection. */
async function sourceDerivedItem(input:{title:string;content:string}){
 const id=randomUUID();
 await insertKnowledgeItem(db.pool,{id,spaceId:space,title:input.title,content:input.content,ownerUserId:owner,createdByUserId:owner,projectId:project});
 await db.pool.query("INSERT INTO provenance_links(id,space_id,target_type,target_id,source_type,source_id,created_at) VALUES($1,$2,'knowledge',$3,'source_item',$4,now())",[randomUUID(),space,id,sourceItem]);
 return id;
}
const reindex=()=>new RetrievalProjectionService(db.pool,knowledgeRetrievalRegistry).reindexAll(space);
/** Admit a report operation and run its real Job; returns the poll. */
async function runReport(op:string,body:object){
 const admitted=await call(op,body);expect(admitted.statusCode,admitted.body).toBe(202);
 const id=admitted.json().data.job_id,registry=new JobHandlerRegistry();registerContentRetrievalJob(registry,config());
 await new PgJobQueueRepository(db.pool).completeJob(id,await registry.dispatch(await claimJobForHandler(db.pool,id)),'test');
 return ()=>app.inject({method:'GET',url:'/api/v1/knowledge/retrieval/requests/'+id});
}
const latest=async(type:string)=>String((await db.pool.query('SELECT id FROM artifacts WHERE space_id=$1 AND artifact_type=$2 ORDER BY created_at DESC,id DESC LIMIT 1',[space,type])).rows[0].id);
const latestProposal=async(type:string)=>String((await db.pool.query('SELECT id FROM proposals WHERE space_id=$1 AND proposal_type=$2 ORDER BY created_at DESC,id DESC LIMIT 1',[space,type])).rows[0].id);
const accept=(id:string)=>app.inject({method:'POST',url:'/api/v1/proposals/'+id+'/accept',headers:{'idempotency-key':randomUUID()}});
const reject=(id:string)=>app.inject({method:'POST',url:'/api/v1/proposals/'+id+'/reject',headers:{'idempotency-key':randomUUID()},payload:{}});
const status=async(id:string)=>String((await db.pool.query('SELECT status FROM proposals WHERE id=$1',[id])).rows[0].status);
/** The children an accepted packet generated, from its stored payload. */
async function children(packet:string){
 const ids=(await db.pool.query('SELECT payload_json FROM proposals WHERE id=$1',[packet])).rows[0].payload_json.generated_child_proposal_ids as string[];
 return (await db.pool.query<{id:string;proposal_type:string;title:string;payload_json:Record<string,unknown>}>('SELECT id,proposal_type,title,payload_json FROM proposals WHERE id=ANY($1::varchar[])',[ids])).rows;
}
const childView=async(id:string)=>({detail:await app.inject({method:'GET',url:'/api/v1/proposals/'+id}),list:await app.inject({method:'GET',url:'/api/v1/proposals?status=pending'})});

beforeEach(async()=>{
 await resetTables(db.pool,['spaces','users'],{cascade:true});space=randomUUID();owner=randomUUID();project=randomUUID();item=randomUUID();
 await seedSpaceOwnerProject(db.pool,{space,owner,project,spaceType:'team'});
 sourceOwner=randomUUID();connection=randomUUID();sourceItem=randomUUID();
 await seedSpaceMember(db.pool,{space,user:sourceOwner});
 await seedSourceConnection(db.pool,{id:connection,space,owner:sourceOwner,consent:consent(true,sourceOwner),policy:{schema_version:1,source_egress_class:'internal_only'}});
 await db.pool.query("INSERT INTO source_items(id,space_id,owner_user_id,visibility,access_level,connection_id,item_type,title,first_seen_at,last_seen_at,content_state,retention_policy,created_at,updated_at) VALUES($1,$2,$3,'space_shared','full',$4,'external_url','Source',now(),now(),'excerpt_saved','summary_only',now(),now())",[sourceItem,space,sourceOwner,connection]);
 app=buildModuleServer(config(),[knowledgeModule,memoryModule,systemActionsModule,artifactsModule,contextOpsModule,proposalsModule,projectsModule]);
 __setAuthIdentityForTests(identity());__setProposalIdentityForTests(identity());
});
afterEach(async()=>{__setAuthIdentityForTests(null);__setProposalIdentityForTests(null);await app?.close();});

describe('child Proposals generated from report packets follow their report closure',()=>{
 /** Withdrawn: type label title, no derived text, nothing PRIVATE in detail or list. */
 async function expectChildWithheld(child:{id:string;proposal_type:string},label:string){
  const v=await childView(child.id);
  expect(v.detail.statusCode,v.detail.body).toBe(200);
  expect(v.detail.json()).toMatchObject({id:child.id,status:'pending',proposed_title:label,proposed_content:'',rationale:'',provenance_entries:null});
  for(const body of [v.detail.body,v.list.body])expect(body).not.toContain('PRIVATE');
  expect(v.list.json().items.find((p:{id:string})=>p.id===child.id)).toMatchObject({proposed_title:label});
 }
 it('withholds a Claim Candidate Packet object_relation_create child (maintenance duplicate) once its Source consent is withdrawn, refuses its accept, and accepts it through the applier once released',async()=>{
  item=await sourceDerivedItem({title:'Lattice PRIVATE title',content:'Quantum lattice PRIVATE body'});
  await sourceDerivedItem({title:'Lattice PRIVATE title',content:'Second lattice PRIVATE body'});
  await reindex();
  await runReport('knowledge.maintenance.scan',{persist_report:true,create_packet:false});
  const maintenance=await latest('retrieval_maintenance_report');
  const packet=await createClaimCandidatePacketFromArtifacts(db.pool,{spaceId:space,ownerUserId:owner,request:{source_artifact_ids:[maintenance],max_candidates:10,review_scope:'private',promote_private_sources_to_space_ops:false}});
  const accepted=await accept(packet.proposalId);expect(accepted.statusCode,accepted.body).toBe(200);
  const child=(await children(packet.proposalId)).find(c=>c.proposal_type==='object_relation_create');
  expect(child,'the duplicate finding generates an object relation child').toBeDefined();
  // The real producer shape: packet context nested under payload.metadata.
  expect(child!.payload_json).toMatchObject({metadata:{source_artifact_ids:[maintenance],claim_candidate_packet:{source_candidate_packet_artifact_id:packet.artifactId}}});
  expect(proposalReportDependencies(child!.proposal_type,child!.payload_json)).toEqual({artifactIds:expect.arrayContaining([packet.artifactId,maintenance]),malformed:false});
  const before=await childView(child!.id);
  expect(before.detail.json().proposed_title).toBe('Review duplicate object relation');
  await setConsent(false);
  await expectChildWithheld(child!,'Object relation create');
  const refused=await accept(child!.id);expect(refused.statusCode,refused.body).toBe(409);
  expect(await status(child!.id)).toBe('pending');
  expect((await db.pool.query('SELECT count(*)::int AS n FROM object_relations WHERE space_id=$1',[space])).rows[0].n).toBe(0);
  await setConsent(true);
  expect((await childView(child!.id)).detail.json().proposed_title).toBe('Review duplicate object relation');
  const applied=await accept(child!.id);expect(applied.statusCode,applied.body).toBe(200);
  expect(await status(child!.id)).toBe('accepted');
 });
 it('withholds a Claim Candidate Packet claim_create child (Brief uncited claim) while its accept waits on the uncommitted withdrawal; reject stays available',async()=>{
  item=await sourceDerivedItem({title:'Lattice PRIVATE title',content:'Quantum lattice PRIVATE body'});
  await reindex();
  // The Brief is the stored output of a synthesis Brief over the
  // Source-derived item (its uncited claim is the LLM stage's output).
  const brief=await insertArtifactRow(db.pool,{spaceId:space,ownerUserId:owner,artifactType:'retrieval_brief',title:'Context Brief',content:'Brief',metadata:{query:'lattice',item_refs:[{object_type:'knowledge_item',object_id:item}],citations:[],gap_analysis:{uncited_claims:['Lattice PRIVATE claim holds for the quantum body.'],contradictions:[],missing_topics:[],stale:[],thin:[]}},canonicalFormat:'retrieval_brief.v1',visibility:'private',runId:null,createdAt:new Date().toISOString()});
  const packet=await createClaimCandidatePacketFromArtifacts(db.pool,{spaceId:space,ownerUserId:owner,request:{source_artifact_ids:[brief],max_candidates:10,review_scope:'private',promote_private_sources_to_space_ops:false}});
  expect((await accept(packet.proposalId)).statusCode).toBe(200);
  const claimChildren=(await children(packet.proposalId)).filter(c=>c.proposal_type==='claim_create');
  expect(claimChildren).toHaveLength(1);
  const child=claimChildren[0]!;
  expect(child.payload_json).toMatchObject({operation:'claim_create',metadata:{source_artifact_ids:[brief],claim_candidate_packet:{source_candidate_packet_artifact_id:packet.artifactId}}});
  expect((await childView(child.id)).detail.json().proposed_title).toContain('Lattice PRIVATE claim');
  const holder=await db.pool.connect();
  try{
   await holder.query('BEGIN');const pid=Number((await holder.query('SELECT pg_backend_pid() AS pid')).rows[0].pid);
   await setConsent(false,holder);
   let done=false;const running=accept(child.id).finally(()=>{done=true;});
   await waitForBlockedBy(db.pool,pid,{settled:()=>done});
   expect(done,'the accept must wait on the uncommitted withdrawal').toBe(false);
   await holder.query('COMMIT');
   const refused=await running;expect(refused.statusCode,refused.body).toBe(409);
  }finally{await holder.query('ROLLBACK').catch(()=>{});holder.release();}
  expect(await status(child.id)).toBe('pending');
  expect((await db.pool.query('SELECT count(*)::int AS n FROM claims WHERE space_id=$1',[space])).rows[0].n).toBe(0);
  await expectChildWithheld(child,'Claim create');
  const rejected=await reject(child.id);expect(rejected.statusCode,rejected.body).toBe(200);
  expect(await status(child.id)).toBe('rejected');
 });
 it('withholds relation discovery object_relation_create and knowledge_create children once their report is withheld; reject is not blocked',async()=>{
  const target=randomUUID();
  await insertKnowledgeItem(db.pool,{id:target,spaceId:space,title:'Helix target',content:'Target body',ownerUserId:owner,createdByUserId:owner,projectId:project});
  item=await sourceDerivedItem({title:'Linker PRIVATE page',content:'See [[Helix target]] and [[Unresolved PRIVATE stub]].'});
  await reindex();
  await runReport('knowledge.relation.discovery.scan',{source_object_types:['knowledge_item'],include_unresolved_item_candidates:true});
  const report=await latest('relation_discovery_report'),packet=await latestProposal('relation_discovery_packet');
  expect((await accept(packet)).statusCode).toBe(200);
  const generated=await children(packet);
  const relation=generated.find(c=>c.proposal_type==='object_relation_create'),stub=generated.find(c=>c.proposal_type==='knowledge_create');
  expect(relation,'resolved link child').toBeDefined();expect(stub,'unresolved link child').toBeDefined();
  for(const child of [relation!,stub!]){
   expect(child.payload_json).toMatchObject({metadata:{relation_discovery_packet:{source_report_artifact_id:report}}});
   expect(proposalReportDependencies(child.proposal_type,child.payload_json)).toEqual({artifactIds:[report],malformed:false});
  }
  expect((await childView(stub!.id)).detail.json().proposed_title).toContain('Unresolved PRIVATE stub');
  await setConsent(false);
  expect(await contentDecisionFromDb(db.pool,identity(),'artifact',report)).toBe('deny');
  await expectChildWithheld(relation!,'Object relation create');
  await expectChildWithheld(stub!,'Knowledge create');
  for(const child of [relation!,stub!]){const r=await accept(child.id);expect(r.statusCode,r.body).toBe(409);expect(await status(child.id)).toBe('pending');}
  expect((await reject(stub!.id)).statusCode).toBe(200);
  await setConsent(true);
  const applied=await accept(relation!.id);expect(applied.statusCode,applied.body).toBe(200);
 });
 it('names nested packet context dependencies and fails closed on a nested context without its report; ordinary Proposals stay ungated',()=>{
  expect(proposalReportDependencies('claim_create',{metadata:{claim_candidate_packet:{source_candidate_packet_proposal_id:'p1',provenance_entries:[{source_type:'proposal',source_id:'p1',source_trust:'derived_review'}]}}})).toEqual({artifactIds:[],malformed:true});
  expect(proposalReportDependencies('knowledge_create',{metadata:{relation_discovery_packet:{source_packet_proposal_id:'p2',source_report_artifact_id:null}}})).toEqual({artifactIds:[],malformed:true});
  expect(proposalReportDependencies('object_relation_create',{metadata:{relation_discovery_packet:'broken'}})).toEqual({artifactIds:[],malformed:true});
  expect(proposalReportDependencies('knowledge_create',{operation:'create',title:'x',metadata:{origin:'manual'}})).toBeNull();
  expect(proposalReportDependencies('claim_create',{operation:'claim_create',claim_text:'x'})).toBeNull();
 });
});

describe('schema suggestions counting published Project public summaries follow the Project closure',()=>{
 async function published(){
  const saved=await call('project.public_summary.save',{project_id:project,summary_text:'Summary PRIVATE text',topics:['topic'],highlights:['finding'],source_refs:[{source_type:'source_connection',source_id:connection}]});
  expect(saved.statusCode,saved.body).toBe(200);
  const pub=await call('project.public_summary.publish',{project_id:project,draft_version:Number(saved.json().data?.draft_version??saved.json().draft_version??1)});
  expect(pub.statusCode,pub.body).toBe(200);
 }
 async function scanned(){
  const poll=await runReport('knowledge.object_schema.suggestions.scan',{base_object_types:['project_public_summary']});
  return {poll,report:await latest('object_schema_suggestion_report')};
 }
 const exits=async(report:string,poll:()=>Promise<{json:()=>{result:unknown};body:string}>)=>({
  detail:await app.inject({method:'GET',url:'/api/v1/artifacts/'+report}),
  list:await app.inject({method:'GET',url:'/api/v1/artifacts'}),
  exported:await app.inject({method:'GET',url:'/api/v1/artifacts/'+report+'/export'}),
  summary:await app.inject({method:'GET',url:'/api/v1/context-ops/summary'}),
  poll:await poll(),
  decision:await contentDecisionFromDb(db.pool,identity(),'artifact',report),
  reader:await assertArtifactReadable(db.pool,identity(),report,'gone').then(()=>'readable',(e:{statusCode?:number})=>e.statusCode),
 });
 async function expectReleased(report:string,poll:()=>Promise<never>){
  const e=await exits(report,poll);
  const finding=e.detail.json().metadata_json?.findings?.find((f:{base_object_type:string})=>f.base_object_type==='project_public_summary');
  expect(finding,e.detail.body).toMatchObject({kind:'missing_object_profile',visible_usage_count:1,evidence_refs:[{object_type:'project_public_summary',object_id:project}]});
  expect(e.list.json().items.find((a:{id:string})=>a.id===report).metadata_json).not.toBeNull();
  expect(e.exported.statusCode).toBe(200);expect(e.poll.json().result).not.toBeNull();
  expect(e.decision).toBe('full');expect(e.reader).toBe('readable');
 }
 async function expectWithheld(report:string,poll:()=>Promise<never>){
  const e=await exits(report,poll);
  expect(e.detail.json()).toMatchObject({id:report,content:null,metadata_json:null,exportable:false,title:'Object schema suggestion report'});
  expect(e.list.json().items.find((a:{id:string})=>a.id===report)).toMatchObject({metadata_json:null,exportable:false});
  for(const body of [e.detail.body,e.list.body,e.summary.body,e.poll.body])expect(body).not.toContain('missing_object_profile');
  expect(e.exported.statusCode).toBe(404);expect(e.poll.json().result).toBeNull();
  expect(e.decision).toBe('deny');expect(e.reader).toBe(404);
 }
 it('names the published summary in its finding and withholds the report at every exit once the summary Source consent is withdrawn, then releases it again',async()=>{
  await published();
  const {poll,report}=await scanned();
  await expectReleased(report,poll as never);
  await setConsent(false);
  await expectWithheld(report,poll as never);
  await setConsent(true);
  await expectReleased(report,poll as never);
 });
 it('withholds the report once the publication is withdrawn, also when the withdrawal commits while the read waits; a rescan with no usage is legitimately empty and released',async()=>{
  await published();
  const {poll,report}=await scanned();
  const revoked=await call('project.public_summary.revoke',{project_id:project});expect(revoked.statusCode,revoked.body).toBe(200);
  await expectWithheld(report,poll as never);
  // Republished: the same report is released again.
  const republished=await call('project.public_summary.publish',{project_id:project,draft_version:1});expect(republished.statusCode,republished.body).toBe(200);
  await expectReleased(report,poll as never);
  const holder=await db.pool.connect();
  try{
   await holder.query('BEGIN');const pid=Number((await holder.query('SELECT pg_backend_pid() AS pid')).rows[0].pid);
   await holder.query('DELETE FROM project_public_summary_publications WHERE space_id=$1 AND project_id=$2',[space,project]);
   let done=false;const running=app.inject({method:'GET',url:'/api/v1/artifacts/'+report}).finally(()=>{done=true;});
   await waitForBlockedBy(db.pool,pid,{settled:()=>done});
   expect(done,'the read must wait on the uncommitted publication withdrawal').toBe(false);
   await holder.query('COMMIT');
   const view=await running;expect(view.json()).toMatchObject({content:null,metadata_json:null});expect(view.body).not.toContain('missing_object_profile');
  }finally{await holder.query('ROLLBACK').catch(()=>{});holder.release();}
  const empty=await scanned();
  const view=await app.inject({method:'GET',url:'/api/v1/artifacts/'+empty.report});
  expect(view.json().metadata_json).toMatchObject({dependency_closure:{version:1},findings:[]});
  expect(await contentDecisionFromDb(db.pool,identity(),'artifact',empty.report)).toBe('full');
  expect((await empty.poll()).json().result).not.toBeNull();
 });
 it('withholds the report once the Project is archived, and fails closed on a stored Project summary count without its ref',async()=>{
  await published();
  const {poll,report}=await scanned();
  const archived=await call('project.archive',{project_id:project});expect(archived.statusCode,archived.body).toBe(200);
  await expectWithheld(report,poll as never);
  const legacy=await insertArtifactRow(db.pool,{spaceId:space,ownerUserId:owner,artifactType:'object_schema_suggestion_report',title:'Object schema suggestions (1)',content:'{}',metadata:{review_scope:'private',dependency_closure:{version:1},findings:[{kind:'missing_object_profile',base_object_type:'project_public_summary',object_profile:'project_public_summary',visible_usage_count:1,evidence_refs:[]}]},canonicalFormat:'object_schema_suggestion_report.v1',visibility:'private',runId:null,createdAt:new Date().toISOString()});
  expect(await contentDecisionFromDb(db.pool,identity(),'artifact',legacy)).toBe('deny');
 });
});
